const e="sFU16FNpu2E",t="sFU16FNpu2E",o="Speak English With Me – React Faster in English ⚡ Day 9 | English Speaking Practice",a="Speak English Daily",i="A1",s="Thử thách theo ngày",d=40,h=1404,r="manual",n=JSON.parse(`[{"start":0,"end":3.13,"text":"Hey, everyone! I'm Emma!","words":[["Hey, everyone!",0],["I'm Emma!",1.5]],"ipa":"/Hey, everyone I'm Emma/"},{"start":3.2,"end":12.23,"text":"Welcome back to Speak English Daily Every day: 20 minutes of focus speaking practice.","words":[["Welcome back to Speak English Daily",3.2],["Every day: 20 minutes of focus speaking practice.",8.13]],"ipa":"/Welcome back to Speak English Daily Every day: 20 minutes of focus speaking practice/"},{"start":12.4,"end":15.3,"text":"No grammar lectures. No textbooks.","words":[["No grammar lectures. No textbooks.",12.4]],"ipa":"/No grammar lectures. No textbooks/"},{"start":15.4,"end":20.67,"text":"Just real English out loud. Every day!","words":[["Just real English out loud. Every day!",15.4]],"ipa":"/Just real English out loud. Every day/"},{"start":20.8,"end":35.27,"text":"Now, quick question before we start: Have you ever been in a situation - where someone asks you something in English, and you understood every word, But your mouth just didn't move?","words":[["Now, quick question before we start:",20.8],["Have you ever been in a situation",24.8],["- where someone asks you something in English,",26.97],["and you understood every word,",29.93],["But your mouth just didn't move?",32.37]],"ipa":"/Now, quick question before we start Have you ever been in a situation where someone asks you something in English and you understood every word But your mouth just didn't move/"},{"start":35.33,"end":38.27,"text":"You know the answer. You know the words.","words":[["You know the answer. You know the words.",35.33]],"ipa":"/You know the answer. You know the words/"},{"start":38.37,"end":44.2,"text":"But there's a gap — A pause And in that pause, you lose confidence.","words":[["But there's a gap — A pause",38.37],["And in that pause, you lose confidence.",41.23]],"ipa":"/But there's a gap — A pause And in that pause, you lose confidence/"},{"start":44.37,"end":45.53,"text":"The moment passes.","words":[["The moment passes.",44.37]],"ipa":"/The moment passes/"},{"start":45.53,"end":48.83,"text":"And you feel frustrated with yourself all over again!","words":[["And you feel frustrated with yourself all over again!",45.53]],"ipa":"/And you feel frustrated with yourself all over again/"},{"start":49.17,"end":53.87,"text":"That gap— that freeze— is not a vocabulary problem.","words":[["That gap— that freeze— is not a vocabulary problem.",49.17]],"ipa":"/That gap— that freeze— is not a vocabulary problem/"},{"start":54.03,"end":56.2,"text":"It is not a grammar problem.","words":[["It is not a grammar problem.",54.03]],"ipa":"/It is not a grammar problem/"},{"start":56.37,"end":61.43,"text":"It is a reaction problem. And reaction is trainable!","words":[["It is a reaction problem. And reaction is trainable!",56.37]],"ipa":"/It is a reaction problem. And reaction is trainable/"},{"start":62.5,"end":65.2,"text":"In Day 8, you responded.","words":[["In Day 8, you responded.",62.5]],"ipa":"/In Day 8, you responded/"},{"start":65.37,"end":67.93,"text":"Today, you respond faster!","words":[["Today, you respond faster!",65.37]],"ipa":"/Today, you respond faster/"},{"start":68.1,"end":72.13,"text":"Not by thinking faster. Not by knowing more words.","words":[["Not by thinking faster. Not by knowing more words.",68.1]],"ipa":"/Not by thinking faster. Not by knowing more words/"},{"start":72.33,"end":78.83,"text":"But by starting sooner. Here is the thing: Most people don't know about fast English speakers.","words":[["But by starting sooner. Here is the thing:",72.33],["Most people don't know about fast English speakers.",75.57]],"ipa":"/But by starting sooner. Here is the thing Most people don't know about fast English speakers/"},{"start":79.23,"end":81.23,"text":"They don't process faster!","words":[["They don't process faster!",79.23]],"ipa":"/They don't process faster/"},{"start":81.53,"end":83.13,"text":"They hesitate less.","words":[["They hesitate less.",81.53]],"ipa":"/They hesitate less/"},{"start":83.13,"end":86.13,"text":"The gap between hearing and speaking.","words":[["The gap between hearing and speaking.",83.13]],"ipa":"/The gap between hearing and speaking/"},{"start":86.23,"end":88.9,"text":"That half-second where most learners freeze.","words":[["That half-second where most learners freeze.",86.23]],"ipa":"/That half-second where most learners freeze/"},{"start":89.2,"end":95.37,"text":"That is what we are training today! Less waiting. More speaking!","words":[["That is what we are training today!",89.2],["Less waiting.",91.3],["More speaking!",92.53]],"ipa":"/That is what we are training today Less waiting More speaking/"},{"start":95.37,"end":100.23,"text":"This is Day 9. Let's go!","words":[["This is Day 9. Let's go!",95.37]],"ipa":"/This is Day 9. Let's go/"},{"start":100.23,"end":107.17,"text":"Quick note before we start: If this is your first time here, welcome — genuinely!","words":[["Quick note before we start:",100.23],["If this is your first time here, welcome — genuinely!",102.83]],"ipa":"/Quick note before we start If this is your first time here, welcome — genuinely/"},{"start":107.17,"end":110.5,"text":"This video is a complete, stand-alone practice session.","words":[["This video is a complete, stand-alone practice session.",107.17]],"ipa":"/This video is a complete, stand-alone practice session/"},{"start":110.63,"end":113.9,"text":"You do not need to have watched any previous videos!","words":[["You do not need to have watched any previous videos!",110.63]],"ipa":"/You do not need to have watched any previous videos/"},{"start":114.17,"end":116.63,"text":"Everything you need is right here!","words":[["Everything you need is right here!",114.17]],"ipa":"/Everything you need is right here/"},{"start":116.8,"end":118.4,"text":"Just follow along.","words":[["Just follow along.",116.8]],"ipa":"/Just follow along/"},{"start":118.5,"end":121.83,"text":"Speak out loud, and it will make complete sense!","words":[["Speak out loud, and it will make complete sense!",118.5]],"ipa":"/Speak out loud, and it will make complete sense/"},{"start":122.03,"end":128.7,"text":"The full playlist and weekly schedule are in the pinned comment below. Whenever you are ready...","words":[["The full playlist and weekly schedule are in the pinned",122.03],["comment below. Whenever you are ready...",124.97]],"ipa":"/The full playlist and weekly schedule are in the pinned comment below. Whenever you are ready/"},{"start":128.7,"end":133.63,"text":"For everyone coming from Day 8 You can already respond.","words":[["For everyone coming from Day 8",128.7],["You can already respond.",131.5]],"ipa":"/For everyone coming from Day 8 You can already respond/"},{"start":133.63,"end":135.9,"text":"Today, we shorten the gap!","words":[["Today, we shorten the gap!",133.63]],"ipa":"/Today, we shorten the gap/"},{"start":136.13,"end":139.13,"text":"Whether you're brand new or on Day 9.","words":[["Whether you're brand new or on Day 9.",136.13]],"ipa":"/Whether you're brand new or on Day 9/"},{"start":139.2,"end":146.2,"text":"This session will work for you! Let's go!","words":[["This session will work for you!",139.2],["Let's go!",143.37]],"ipa":"/This session will work for you Let's go/"},{"start":146.2,"end":153.23,"text":"Now, I want to reframe something, Because most people think about speed the wrong way.","words":[["Now, I want to reframe something,",146.2],["Because most people think about speed the wrong way.",149.6]],"ipa":"/Now, I want to reframe something Because most people think about speed the wrong way/"},{"start":153.3,"end":155.8,"text":"They think: \\"I need to speak faster!\\"","words":[["They think: \\"I need to speak faster!\\"",153.3]],"ipa":"/They think: \\"I need to speak faster/"},{"start":155.8,"end":159.8,"text":"Wrong! You don't need better English to sound faster.","words":[["Wrong! You don't need better English to sound faster.",155.8]],"ipa":"/Wrong! You don't need better English to sound faster/"},{"start":159.93,"end":162.33,"text":"You need less hesitation!","words":[["You need less hesitation!",159.93]],"ipa":"/You need less hesitation/"},{"start":162.33,"end":166.9,"text":"Watch what happens in a slow response: Someone asks you something.","words":[["Watch what happens in a slow response:",162.33],["Someone asks you something.",165.17]],"ipa":"/Watch what happens in a slow response Someone asks you something/"},{"start":166.93,"end":168.03,"text":"You hear it.","words":[["You hear it.",166.93]],"ipa":"/You hear it/"},{"start":168.03,"end":171.23,"text":"You wait one second, two seconds.","words":[["You wait one second, two seconds.",168.03]],"ipa":"/You wait one second, two seconds/"},{"start":171.23,"end":173.4,"text":"You think about it. You translate.","words":[["You think about it.",171.23],["You translate.",172.33]],"ipa":"/You think about it You translate/"},{"start":173.4,"end":175.1,"text":"You build a sentence.","words":[["You build a sentence.",173.4]],"ipa":"/You build a sentence/"},{"start":175.1,"end":176.4,"text":"Then you speak.","words":[["Then you speak.",175.1]],"ipa":"/Then you speak/"},{"start":176.4,"end":179.53,"text":"That pause right there is the problem.","words":[["That pause right there is the problem.",176.4]],"ipa":"/That pause right there is the problem/"},{"start":179.53,"end":183.57,"text":"Not your English. The pause!","words":[["Not your English. The pause!",179.53]],"ipa":"/Not your English. The pause/"},{"start":183.57,"end":186.13,"text":"Today, we shrink that pause!","words":[["Today, we shrink that pause!",183.57]],"ipa":"/Today, we shrink that pause/"},{"start":186.3,"end":188.8,"text":"Not to zero. Just smaller.","words":[["Not to zero. Just smaller.",186.3]],"ipa":"/Not to zero. Just smaller/"},{"start":188.8,"end":192.5,"text":"Much smaller. The rule for today is simple.","words":[["Much smaller. The rule for today is simple.",188.8]],"ipa":"/Much smaller. The rule for today is simple/"},{"start":192.5,"end":195.17,"text":"Start speaking before you feel ready!","words":[["Start speaking before you feel ready!",192.5]],"ipa":"/Start speaking before you feel ready/"},{"start":195.17,"end":198.43,"text":"The words will follow. They always do.","words":[["The words will follow. They always do.",195.17]],"ipa":"/The words will follow. They always do/"},{"start":198.43,"end":201.17,"text":"Let's prove it!","words":[["Let's prove it!",198.43]],"ipa":"/Let's prove it/"},{"start":201.17,"end":203.47,"text":"Same questions as Day 8.","words":[["Same questions as Day 8.",201.17]],"ipa":"/Same questions as Day 8/"},{"start":203.47,"end":206.33,"text":"But today the pause is shorter.","words":[["But today the pause is shorter.",203.47]],"ipa":"/But today the pause is shorter/"},{"start":206.33,"end":209.37,"text":"In Day 8, you had four to six seconds.","words":[["In Day 8, you had four to six seconds.",206.33]],"ipa":"/In Day 8, you had four to six seconds/"},{"start":209.43,"end":211.77,"text":"Today, you have three seconds.","words":[["Today, you have three seconds.",209.43]],"ipa":"/Today, you have three seconds/"},{"start":211.77,"end":214.77,"text":"Maybe less. You might feel nervous.","words":[["Maybe less. You might feel nervous.",211.77]],"ipa":"/Maybe less. You might feel nervous/"},{"start":214.77,"end":216.93,"text":"That is completely normal!","words":[["That is completely normal!",214.77]],"ipa":"/That is completely normal/"},{"start":216.93,"end":217.83,"text":"Do it anyway.","words":[["Do it anyway.",216.93]],"ipa":"/Do it anyway/"},{"start":217.83,"end":222.97,"text":"The nervous feeling is your brain adjusting to a new speed. That adjustment.","words":[["The nervous feeling is your brain",217.83],["adjusting to a new speed. That adjustment.",219.97]],"ipa":"/The nervous feeling is your brain adjusting to a new speed. That adjustment/"},{"start":222.97,"end":224.27,"text":"That is progress.","words":[["That is progress.",222.97]],"ipa":"/That is progress/"},{"start":224.27,"end":226.67,"text":"Don't wait until you feel ready.","words":[["Don't wait until you feel ready.",224.27]],"ipa":"/Don't wait until you feel ready/"},{"start":226.73,"end":231.03,"text":"Start. The sentence will come!","words":[["Start. The sentence will come!",226.73]],"ipa":"/Start. The sentence will come/"},{"start":231.33,"end":239.1,"text":"\\"How are you?\\"","words":[["\\"How are you?\\"",231.33]],"ipa":"/How are you/"},{"start":239.3,"end":246.17,"text":"I'm good. Thanks. How about you?","words":[["I'm good. Thanks. How about you?",239.3]],"ipa":"/I'm good. Thanks. How about you/"},{"start":246.27,"end":253.83,"text":"I'm good. Thanks. How about you?","words":[["I'm good. Thanks. How about you?",246.27]],"ipa":"/I'm good. Thanks. How about you/"},{"start":253.83,"end":257.77,"text":"The moment you hear, you start speaking!","words":[["The moment you hear, you start speaking!",253.83]],"ipa":"/The moment you hear, you start speaking/"},{"start":257.77,"end":261.03,"text":"Don't wait for silence. Go on the last word!","words":[["Don't wait for silence. Go on the last word!",257.77]],"ipa":"/Don't wait for silence. Go on the last word/"},{"start":261.03,"end":263.13,"text":"You already know this answer!","words":[["You already know this answer!",261.03]],"ipa":"/You already know this answer/"},{"start":263.13,"end":267.53,"text":"Your mouth knows it. Trust it!","words":[["Your mouth knows it. Trust it!",263.13]],"ipa":"/Your mouth knows it. Trust it/"},{"start":267.53,"end":275.63,"text":"Someone says: \\"How's it going?\\"","words":[["Someone says: \\"How's it going?\\"",267.53]],"ipa":"/Someone says: \\"How's it going/"},{"start":275.7,"end":284.77,"text":"You say: Pretty good. Just keeping busy!","words":[["You say:",275.7],["Pretty good. Just keeping busy!",277.03]],"ipa":"/You say Pretty good. Just keeping busy/"},{"start":284.77,"end":292.47,"text":"Pretty good. Just keeping busy!","words":[["Pretty good. Just keeping busy!",284.77]],"ipa":"/Pretty good. Just keeping busy/"},{"start":292.47,"end":296.37,"text":"Two words to start: \\"Pretty good.\\"","words":[["Two words to start: \\"Pretty good.\\"",292.47]],"ipa":"/Two words to start: \\"Pretty good/"},{"start":296.37,"end":300.77,"text":"Just get those two out. The rest follows automatically!","words":[["Just get those two out. The rest follows automatically!",296.37]],"ipa":"/Just get those two out. The rest follows automatically/"},{"start":300.77,"end":303.37,"text":"Short answers are fast answers!","words":[["Short answers are fast answers!",300.77]],"ipa":"/Short answers are fast answers/"},{"start":303.37,"end":306.7,"text":"Short is not wrong. Short is real.","words":[["Short is not wrong. Short is real.",303.37]],"ipa":"/Short is not wrong. Short is real/"},{"start":306.7,"end":311.9,"text":"Good. That was faster than Day 8. Keep going!","words":[["Good. That was faster than Day 8. Keep going!",306.7]],"ipa":"/Good. That was faster than Day 8. Keep going/"},{"start":311.9,"end":320,"text":"Someone says: \\"Are you busy right now?\\"","words":[["Someone says: \\"Are you busy right now?\\"",311.9]],"ipa":"/Someone says: \\"Are you busy right now/"},{"start":320.2,"end":327.8,"text":"A little bit, yeah. What's up?","words":[["A little bit, yeah. What's up?",320.2]],"ipa":"/A little bit, yeah. What's up/"},{"start":327.8,"end":335.4,"text":"A little bit, yeah. What's up?","words":[["A little bit, yeah. What's up?",327.8]],"ipa":"/A little bit, yeah. What's up/"},{"start":335.47,"end":342.83,"text":"Start with \\"a little\\"—that buys you a half-second - while sounding completely natural!","words":[["Start with \\"a little\\"—that buys you a half-second",335.47],["- while sounding completely natural!",340.03]],"ipa":"/Start with \\"a little\\"—that buys you a half-second while sounding completely natural/"},{"start":342.83,"end":346.97,"text":"Filler phrases like \\"a little\\" and \\"kind of\\" are tools.","words":[["Filler phrases like \\"a little\\" and \\"kind of\\" are tools.",342.83]],"ipa":"/Filler phrases like \\"a little\\" and \\"kind of\\" are tools/"},{"start":346.97,"end":350.57,"text":"Use them to start faster!","words":[["Use them to start faster!",346.97]],"ipa":"/Use them to start faster/"},{"start":350.8,"end":359.9,"text":"Someone says, \\"Did you sleep well?\\"","words":[["Someone says, \\"Did you sleep well?\\"",350.8]],"ipa":"/Someone says, \\"Did you sleep well/"},{"start":360.13,"end":369.63,"text":"Yeah, not bad. A little tired but okay.","words":[["Yeah, not bad. A little tired but okay.",360.13]],"ipa":"/Yeah, not bad. A little tired but okay/"},{"start":369.63,"end":379.4,"text":"Yeah, not bad. A little tired but okay.","words":[["Yeah, not bad. A little tired but okay.",369.63]],"ipa":"/Yeah, not bad. A little tired but okay/"},{"start":379.43,"end":384.13,"text":"Start with \\"Yeah.\\"—one syllable. Instantly buys time.","words":[["Start with \\"Yeah.\\"—one syllable. Instantly buys time.",379.43]],"ipa":"/Start with \\"Yeah.\\"—one syllable. Instantly buys time/"},{"start":384.13,"end":386.3,"text":"Sounds completely native.","words":[["Sounds completely native.",384.13]],"ipa":"/Sounds completely native/"},{"start":386.3,"end":393.6,"text":"\\"Yeah\\" as your first word is one of the most powerful tools in fast English conversation.","words":[["\\"Yeah\\" as your first word is one of the most powerful tools",386.3],["in fast English conversation.",389.9]],"ipa":"/Yeah\\" as your first word is one of the most powerful tools in fast English conversation/"},{"start":395.07,"end":403.33,"text":"\\"Have you eaten yet?\\"","words":[["\\"Have you eaten yet?\\"",395.07]],"ipa":"/Have you eaten yet/"},{"start":403.57,"end":412.23,"text":"Not yet. I was just about to.","words":[["Not yet. I was just about to.",403.57]],"ipa":"/Not yet. I was just about to/"},{"start":412.53,"end":420.8,"text":"Not yet. I was just about to.","words":[["Not yet. I was just about to.",412.53]],"ipa":"/Not yet. I was just about to/"},{"start":421.13,"end":423.57,"text":"Start with \\"Not yet.\\"","words":[["Start with \\"Not yet.\\"",421.13]],"ipa":"/Start with \\"Not yet/"},{"start":423.6,"end":428.37,"text":"- two words that answer the question completely, while you think of the rest!","words":[["- two words that answer the question completely,",423.6],["while you think of the rest!",426.67]],"ipa":"/two words that answer the question completely while you think of the rest/"},{"start":428.53,"end":432.3,"text":"Answer the core question first, then add detail.","words":[["Answer the core question first, then add detail.",428.53]],"ipa":"/Answer the core question first, then add detail/"},{"start":432.43,"end":436.37,"text":"That is the fast speaker's technique!","words":[["That is the fast speaker's technique!",432.43]],"ipa":"/That is the fast speaker's technique/"},{"start":436.53,"end":440.83,"text":"Good! You're already responding faster!","words":[["Good! You're already responding faster!",436.53]],"ipa":"/Good! You're already responding faster/"},{"start":440.83,"end":444.47,"text":"Feel that difference!","words":[["Feel that difference!",440.83]],"ipa":"/Feel that difference/"},{"start":444.6,"end":454.03,"text":"Someone says: \\"Do you have a moment?\\"","words":[["Someone says:",444.6],["\\"Do you have a moment?\\"",445.83]],"ipa":"/Someone says Do you have a moment/"},{"start":454.2,"end":461.5,"text":"Sure. What do you need?","words":[["Sure. What do you need?",454.2]],"ipa":"/Sure. What do you need/"},{"start":461.63,"end":469,"text":"Sure. What do you need?","words":[["Sure. What do you need?",461.63]],"ipa":"/Sure. What do you need/"},{"start":469.33,"end":474.07,"text":"\\"Sure\\"—one word. Committed. Warm. Immediate!","words":[["\\"Sure\\"—one word. Committed. Warm. Immediate!",469.33]],"ipa":"/Sure\\"—one word. Committed. Warm. Immediate/"},{"start":474.2,"end":476.27,"text":"Everything else flows from it!","words":[["Everything else flows from it!",474.2]],"ipa":"/Everything else flows from it/"},{"start":476.37,"end":485.1,"text":"Single-word starters —\\"Sure,\\" \\"Yeah,\\" \\"Of course\\"—are the fastest responses in English!","words":[["Single-word starters —\\"Sure,\\" \\"Yeah,\\"",476.37],["\\"Of course\\"—are the fastest responses in English!",479.8]],"ipa":"/Single-word starters —\\"Sure,\\" \\"Yeah Of course\\"—are the fastest responses in English/"},{"start":485.37,"end":490.57,"text":"Six questions. All familiar from Day 8. But today—faster!","words":[["Six questions. All familiar from Day 8.",485.37],["But today—faster!",488.6]],"ipa":"/Six questions. All familiar from Day 8 But today—faster/"},{"start":490.6,"end":493.17,"text":"Your mouth already knows these answers!","words":[["Your mouth already knows these answers!",490.6]],"ipa":"/Your mouth already knows these answers/"},{"start":493.17,"end":496.87,"text":"The only thing we changed is how long you waited before starting.","words":[["The only thing we changed is how long you waited before starting.",493.17]],"ipa":"/The only thing we changed is how long you waited before starting/"},{"start":496.87,"end":498.83,"text":"Six answers out.","words":[["Six answers out.",496.87]],"ipa":"/Six answers out/"},{"start":498.83,"end":501.6,"text":"Six times you started before you were ready.","words":[["Six times you started before you were ready.",498.83]],"ipa":"/Six times you started before you were ready/"},{"start":501.6,"end":503.77,"text":"- and every timel, you finished!","words":[["- and every timel, you finished!",501.6]],"ipa":"/and every timel, you finished/"},{"start":503.77,"end":506.13,"text":"That is the proof!","words":[["That is the proof!",503.77]],"ipa":"/That is the proof/"},{"start":506.13,"end":508.03,"text":"Remember that feeling.","words":[["Remember that feeling.",506.13]],"ipa":"/Remember that feeling/"},{"start":508.1,"end":511.53,"text":"Now we push it further!","words":[["Now we push it further!",508.1]],"ipa":"/Now we push it further/"},{"start":511.53,"end":515.2,"text":"Now, the core training of Day 9.","words":[["Now, the core training of Day 9.",511.53]],"ipa":"/Now, the core training of Day 9/"},{"start":515.2,"end":517.03,"text":"Quick reaction round.","words":[["Quick reaction round.",515.2]],"ipa":"/Quick reaction round/"},{"start":517.03,"end":520.1,"text":"I ask. You answer before you feel ready.","words":[["I ask. You answer before you feel ready.",517.03]],"ipa":"/I ask. You answer before you feel ready/"},{"start":520.1,"end":523.43,"text":"That is the rule. That is the only rule.","words":[["That is the rule. That is the only rule.",520.1]],"ipa":"/That is the rule. That is the only rule/"},{"start":523.43,"end":528.4,"text":"We are using familiar questions Things your mouth already knows.","words":[["We are using familiar questions",523.43],["Things your mouth already knows.",525.93]],"ipa":"/We are using familiar questions Things your mouth already knows/"},{"start":528.4,"end":530.77,"text":"The goal is not the answer.","words":[["The goal is not the answer.",528.4]],"ipa":"/The goal is not the answer/"},{"start":530.77,"end":532.83,"text":"The goal is the timing!","words":[["The goal is the timing!",530.77]],"ipa":"/The goal is the timing/"},{"start":532.83,"end":536.03,"text":"Start speaking before your brain says it's ready!","words":[["Start speaking before your brain says it's ready!",532.83]],"ipa":"/Start speaking before your brain says it's ready/"},{"start":536.03,"end":540.67,"text":"Your mouth will catch up. It always does!","words":[["Your mouth will catch up. It always does!",536.03]],"ipa":"/Your mouth will catch up. It always does/"},{"start":540.67,"end":548.77,"text":"\\"What are you doing?\\"","words":[["\\"What are you doing?\\"",540.67]],"ipa":"/What are you doing/"},{"start":548.97,"end":553.63,"text":"→ Just practicing my English!","words":[["→ Just practicing my English!",548.97]],"ipa":"/Just practicing my English/"},{"start":553.67,"end":560.4,"text":"Your first word is \\"Just\\" — easy, casual, immediate.","words":[["Your first word is \\"Just\\" — easy, casual, immediate.",553.67]],"ipa":"/Your first word is \\"Just\\" — easy, casual, immediate/"},{"start":560.57,"end":565.37,"text":"Don't think about the rest. Start with \\"just.\\"","words":[["Don't think about the rest. Start with \\"just.\\"",560.57]],"ipa":"/Don't think about the rest. Start with \\"just/"},{"start":565.73,"end":572.27,"text":"\\"Ready to go?\\"","words":[["\\"Ready to go?\\"",565.73]],"ipa":"/Ready to go/"},{"start":572.43,"end":577.77,"text":"→ Almost. Give me one second.","words":[["→ Almost. Give me one second.",572.43]],"ipa":"/Almost. Give me one second/"},{"start":577.9,"end":582.03,"text":"Good! You started before you felt ready!","words":[["Good! You started before you felt ready!",577.9]],"ipa":"/Good! You started before you felt ready/"},{"start":582.23,"end":585.87,"text":"That is exactly it!","words":[["That is exactly it!",582.23]],"ipa":"/That is exactly it/"},{"start":586.17,"end":590.07,"text":"\\"Almost\\" — one word that answers completely.","words":[["\\"Almost\\" — one word that answers completely.",586.17]],"ipa":"/Almost\\" — one word that answers completely/"},{"start":590.23,"end":601.8,"text":"Say it before you finish thinking, Then add the rest! \\"Long day?\\"","words":[["Say it before you finish thinking,",590.23],["Then add the rest!",592.33],["\\"Long day?\\"",594.93]],"ipa":"/Say it before you finish thinking Then add the rest Long day/"},{"start":602.03,"end":608.2,"text":"→ Yeah, a little. But I'm okay.","words":[["→ Yeah, a little. But I'm okay.",602.03]],"ipa":"/Yeah, a little. But I'm okay/"},{"start":608.47,"end":618.53,"text":"Start with \\"Yeah.\\" Every time you're unsure, It never sounds wrong. It always sounds natural!","words":[["Start with \\"Yeah.\\" Every time you're unsure,",608.47],["It never sounds wrong. It always sounds natural!",612.63]],"ipa":"/Start with \\"Yeah.\\" Every time you're unsure It never sounds wrong. It always sounds natural/"},{"start":618.73,"end":626.2,"text":"\\"Are you from around here?\\"","words":[["\\"Are you from around here?\\"",618.73]],"ipa":"/Are you from around here/"},{"start":626.37,"end":632.63,"text":"→ No, I'm not. I'm from Japan.","words":[["→ No, I'm not. I'm from Japan.",626.37]],"ipa":"/No, I'm not. I'm from Japan/"},{"start":632.8,"end":637.8,"text":"\\"No, I'm not\\" — four syllables that answer the question fully.","words":[["\\"No, I'm not\\" — four syllables that answer the question fully.",632.8]],"ipa":"/No, I'm not\\" — four syllables that answer the question fully/"},{"start":638.03,"end":642.43,"text":"Then the location. Clean and fast.","words":[["Then the location. Clean and fast.",638.03]],"ipa":"/Then the location. Clean and fast/"},{"start":642.6,"end":649.97,"text":"\\"Can I ask you something?\\"","words":[["\\"Can I ask you something?\\"",642.6]],"ipa":"/Can I ask you something/"},{"start":650.03,"end":654.23,"text":"→ Sure. Go ahead.","words":[["→ Sure. Go ahead.",650.03]],"ipa":"/Sure. Go ahead/"},{"start":654.3,"end":658.17,"text":"Two words—done! Short is fast!","words":[["Two words—done! Short is fast!",654.3]],"ipa":"/Two words—done! Short is fast/"},{"start":658.27,"end":663.13,"text":"Short is confident. Short is completely natural!","words":[["Short is confident. Short is completely natural!",658.27]],"ipa":"/Short is confident. Short is completely natural/"},{"start":663.27,"end":666.2,"text":"Good! The quick-start drill!","words":[["Good! The quick-start drill!",663.27]],"ipa":"/Good! The quick-start drill/"},{"start":666.43,"end":671.67,"text":"Every time. That is your new speed.","words":[["Every time. That is your new speed.",666.43]],"ipa":"/Every time. That is your new speed/"},{"start":671.93,"end":679.93,"text":"\\"What time is it?\\"","words":[["\\"What time is it?\\"",671.93]],"ipa":"/What time is it/"},{"start":679.93,"end":686.8,"text":"→ I'm not sure. Let me check.","words":[["→ I'm not sure. Let me check.",679.93]],"ipa":"/I'm not sure. Let me check/"},{"start":687.03,"end":689.53,"text":"You don't need to know the time.","words":[["You don't need to know the time.",687.03]],"ipa":"/You don't need to know the time/"},{"start":689.6,"end":695.17,"text":"\\"I'm not sure\\" is a complete, natural, immediate answer!","words":[["\\"I'm not sure\\" is a complete, natural, immediate answer!",689.6]],"ipa":"/I'm not sure\\" is a complete, natural, immediate answer/"},{"start":695.33,"end":703.83,"text":"\\"Do you speak English well?\\"","words":[["\\"Do you speak English well?\\"",695.33]],"ipa":"/Do you speak English well/"},{"start":703.9,"end":712.2,"text":"→ I'm working on it. Getting better every day.","words":[["→ I'm working on it. Getting better every day.",703.9]],"ipa":"/I'm working on it. Getting better every day/"},{"start":712.53,"end":722.97,"text":"Don't overthink this one. \\"I'm working on it\\"— - four words. Out. Before you second-guess yourself! Seven drills!","words":[["Don't overthink this one. \\"I'm working on it\\"—",712.53],["- four words. Out. Before you second-guess yourself!",715.83],["Seven drills!",721.3]],"ipa":"/Don't overthink this one. \\"I'm working on it four words. Out. Before you second-guess yourself Seven drills/"},{"start":722.97,"end":726.53,"text":"Every one of them—you started before you felt ready!","words":[["Every one of them—you started before you felt ready!",722.97]],"ipa":"/Every one of them—you started before you felt ready/"},{"start":726.63,"end":729.3,"text":"And every one of them—you finished!","words":[["And every one of them—you finished!",726.63]],"ipa":"/And every one of them—you finished/"},{"start":729.3,"end":730.9,"text":"That is the lesson.","words":[["That is the lesson.",729.3]],"ipa":"/That is the lesson/"},{"start":730.9,"end":733.67,"text":"That was faster than you expected, right?","words":[["That was faster than you expected, right?",730.9]],"ipa":"/That was faster than you expected, right/"},{"start":733.67,"end":737.33,"text":"That is what happens when you stop waiting and just start.","words":[["That is what happens when you stop waiting and just start.",733.67]],"ipa":"/That is what happens when you stop waiting and just start/"},{"start":737.33,"end":742.33,"text":"Your mouth already knows more than your brain gives it credit for.","words":[["Your mouth already knows more than your brain gives it credit for.",737.33]],"ipa":"/Your mouth already knows more than your brain gives it credit for/"},{"start":742.33,"end":744.9,"text":"The hesitation is not gone.","words":[["The hesitation is not gone.",742.33]],"ipa":"/The hesitation is not gone/"},{"start":745.03,"end":750.93,"text":"But it is smaller. And every day, it gets smaller!","words":[["But it is smaller. And every day, it gets smaller!",745.03]],"ipa":"/But it is smaller. And every day, it gets smaller/"},{"start":750.93,"end":753.7,"text":"Now, you're going to hear Alex.","words":[["Now, you're going to hear Alex.",750.93]],"ipa":"/Now, you're going to hear Alex/"},{"start":753.83,"end":755.63,"text":"He'll talk to you directly.","words":[["He'll talk to you directly.",753.83]],"ipa":"/He'll talk to you directly/"},{"start":755.7,"end":758.9,"text":"Real situations. Short exchanges!","words":[["Real situations. Short exchanges!",755.7]],"ipa":"/Real situations. Short exchanges/"},{"start":758.9,"end":761.33,"text":"You respond out loud every time!","words":[["You respond out loud every time!",758.9]],"ipa":"/You respond out loud every time/"},{"start":761.33,"end":764.77,"text":"Then I give you a model answer and we repeat together!","words":[["Then I give you a model answer and we repeat together!",761.33]],"ipa":"/Then I give you a model answer and we repeat together/"},{"start":764.77,"end":766.6,"text":"Same goal as Day 8.","words":[["Same goal as Day 8.",764.77]],"ipa":"/Same goal as Day 8/"},{"start":766.6,"end":770,"text":"But today you open your mouth faster!","words":[["But today you open your mouth faster!",766.6]],"ipa":"/But today you open your mouth faster/"},{"start":770,"end":773.43,"text":"Today, one instruction changes everything!","words":[["Today, one instruction changes everything!",770]],"ipa":"/Today, one instruction changes everything/"},{"start":773.43,"end":775.9,"text":"Answer before you finish thinking!","words":[["Answer before you finish thinking!",773.43]],"ipa":"/Answer before you finish thinking/"},{"start":775.93,"end":779.33,"text":"Don't wait until the sentence is complete in your head!","words":[["Don't wait until the sentence is complete in your head!",775.93]],"ipa":"/Don't wait until the sentence is complete in your head/"},{"start":779.33,"end":781.47,"text":"Start with the first word that comes.","words":[["Start with the first word that comes.",779.33]],"ipa":"/Start with the first word that comes/"},{"start":781.57,"end":783.43,"text":"The rest will follow!","words":[["The rest will follow!",781.57]],"ipa":"/The rest will follow/"},{"start":783.43,"end":788.2,"text":"Real conversations work exactly this way!","words":[["Real conversations work exactly this way!",783.43]],"ipa":"/Real conversations work exactly this way/"},{"start":788.2,"end":793.6,"text":"Situation 1: Someone checks in on you!","words":[["Situation 1: Someone checks in on you!",788.2]],"ipa":"/Situation 1: Someone checks in on you/"},{"start":793.87,"end":804.23,"text":"Hey, you doing okay today? You seem a little quiet.","words":[["Hey, you doing okay today? You seem a little quiet.",793.87]],"ipa":"/Hey, you doing okay today? You seem a little quiet/"},{"start":804.23,"end":813.83,"text":"Yeah, just a bit tired. I'm fine though. Thanks.","words":[["Yeah, just a bit tired. I'm fine though. Thanks.",804.23]],"ipa":"/Yeah, just a bit tired. I'm fine though. Thanks/"},{"start":814.07,"end":824.13,"text":"Yeah, just a bit tired. I'm fine though. Thanks.","words":[["Yeah, just a bit tired. I'm fine though. Thanks.",814.07]],"ipa":"/Yeah, just a bit tired. I'm fine though. Thanks/"},{"start":824.3,"end":828.93,"text":"Start with \\"Yeah\\" before the full answer forms!","words":[["Start with \\"Yeah\\" before the full answer forms!",824.3]],"ipa":"/Start with \\"Yeah\\" before the full answer forms/"},{"start":829.17,"end":833.43,"text":"One word opens the door. The rest walks through!","words":[["One word opens the door. The rest walks through!",829.17]],"ipa":"/One word opens the door. The rest walks through/"},{"start":833.43,"end":837.57,"text":"Real people start answers before they finish forming them.","words":[["Real people start answers before they finish forming them.",833.43]],"ipa":"/Real people start answers before they finish forming them/"},{"start":837.57,"end":842.1,"text":"That is how natural conversation flows!","words":[["That is how natural conversation flows!",837.57]],"ipa":"/That is how natural conversation flows/"},{"start":842.1,"end":847.77,"text":"Situation 2: Planning lunch!","words":[["Situation 2: Planning lunch!",842.1]],"ipa":"/Situation 2: Planning lunch/"},{"start":848.37,"end":856.47,"text":"\\"Want to grab something to eat?\\"","words":[["\\"Want to grab something to eat?\\"",848.37]],"ipa":"/Want to grab something to eat/"},{"start":856.93,"end":865.2,"text":"Sure, why not. Where do you want to go?","words":[["Sure, why not. Where do you want to go?",856.93]],"ipa":"/Sure, why not. Where do you want to go/"},{"start":865.53,"end":873.67,"text":"Sure, why not. Where do you want to go?","words":[["Sure, why not. Where do you want to go?",865.53]],"ipa":"/Sure, why not. Where do you want to go/"},{"start":874.03,"end":879.43,"text":"\\"Sure, why not\\" — three words, immediate, casual.","words":[["\\"Sure, why not\\" — three words, immediate, casual.",874.03]],"ipa":"/Sure, why not\\" — three words, immediate, casual/"},{"start":879.57,"end":882.43,"text":"Then turn it back with a question to keep it going.","words":[["Then turn it back with a question to keep it going.",879.57]],"ipa":"/Then turn it back with a question to keep it going/"},{"start":882.73,"end":888.13,"text":"Turning the question back buys you time And keeps the conversation alive!","words":[["Turning the question back buys you time",882.73],["And keeps the conversation alive!",885.5]],"ipa":"/Turning the question back buys you time And keeps the conversation alive/"},{"start":888.23,"end":892.27,"text":"Two benefits, zero effort.","words":[["Two benefits, zero effort.",888.23]],"ipa":"/Two benefits, zero effort/"},{"start":892.57,"end":899.73,"text":"Situation 3: Someone asks about your weekend plans!","words":[["Situation 3: Someone asks about your weekend plans!",892.57]],"ipa":"/Situation 3: Someone asks about your weekend plans/"},{"start":899.73,"end":908.13,"text":"\\"Any plans for the weekend?\\"","words":[["\\"Any plans for the weekend?\\"",899.73]],"ipa":"/Any plans for the weekend/"},{"start":908.57,"end":921.6,"text":"Not really. Probably just staying home. Maybe see some friends.","words":[["Not really. Probably just staying home. Maybe see some friends.",908.57]],"ipa":"/Not really. Probably just staying home. Maybe see some friends/"},{"start":922.13,"end":935.23,"text":"Not really. Probably just staying home. Maybe see some friends.","words":[["Not really. Probably just staying home. Maybe see some friends.",922.13]],"ipa":"/Not really. Probably just staying home. Maybe see some friends/"},{"start":935.63,"end":940.37,"text":"Start with \\"Not really\\" before you know what comes next!","words":[["Start with \\"Not really\\" before you know what comes next!",935.63]],"ipa":"/Start with \\"Not really\\" before you know what comes next/"},{"start":940.57,"end":942.9,"text":"The details follow naturally.","words":[["The details follow naturally.",940.57]],"ipa":"/The details follow naturally/"},{"start":943.13,"end":953.37,"text":"\\"Not really\\" + \\"probably\\" + \\"maybe\\" — three soft words that make any answer sound relaxed and real.","words":[["\\"Not really\\" + \\"probably\\" + \\"maybe\\"",943.13],["— three soft words that make any answer sound relaxed and real.",946.73]],"ipa":"/Not really\\" + \\"probably\\" + \\"maybe three soft words that make any answer sound relaxed and real/"},{"start":953.37,"end":958.93,"text":"Situation 4: Wrapping up a call!","words":[["Situation 4: Wrapping up a call!",953.37]],"ipa":"/Situation 4: Wrapping up a call/"},{"start":959.63,"end":971.8,"text":"\\"Okay, I think that covers everything. Sound good?\\"","words":[["\\"Okay, I think that covers everything. Sound good?\\"",959.63]],"ipa":"/Okay, I think that covers everything. Sound good/"},{"start":971.93,"end":979.83,"text":"Yeah, sounds good. Talk soon.","words":[["Yeah, sounds good. Talk soon.",971.93]],"ipa":"/Yeah, sounds good. Talk soon/"},{"start":980.53,"end":988.03,"text":"Yeah, sounds good. Talk soon.","words":[["Yeah, sounds good. Talk soon.",980.53]],"ipa":"/Yeah, sounds good. Talk soon/"},{"start":989.2,"end":993.17,"text":"Four words. Complete. Natural. Immediate!","words":[["Four words. Complete. Natural. Immediate!",989.2]],"ipa":"/Four words. Complete. Natural. Immediate/"},{"start":993.17,"end":994.87,"text":"You don't need more.","words":[["You don't need more.",993.17]],"ipa":"/You don't need more/"},{"start":994.87,"end":997.93,"text":"Ending conversations fast is a skill.","words":[["Ending conversations fast is a skill.",994.87]],"ipa":"/Ending conversations fast is a skill/"},{"start":997.93,"end":1000.53,"text":"\\"Yeah, sounds good. Talk soon.\\"","words":[["\\"Yeah, sounds good. Talk soon.\\"",997.93]],"ipa":"/Yeah, sounds good. Talk soon/"},{"start":1000.57,"end":1005.73,"text":"These six words close any conversation perfectly.","words":[["These six words close any conversation perfectly.",1000.57]],"ipa":"/These six words close any conversation perfectly/"},{"start":1005.97,"end":1010.23,"text":"Situation 5: Someone compliments your work!","words":[["Situation 5: Someone compliments your work!",1005.97]],"ipa":"/Situation 5: Someone compliments your work/"},{"start":1012.13,"end":1025.97,"text":"\\"Hey, good job on that report. Really clear!\\"","words":[["\\"Hey, good job on that report. Really clear!\\"",1012.13]],"ipa":"/Hey, good job on that report. Really clear/"},{"start":1026.5,"end":1035.67,"text":"Oh thanks. I'm glad it worked out.","words":[["Oh thanks. I'm glad it worked out.",1026.5]],"ipa":"/Oh thanks. I'm glad it worked out/"},{"start":1036.03,"end":1045.83,"text":"Oh thanks. I'm glad it worked out.","words":[["Oh thanks. I'm glad it worked out.",1036.03]],"ipa":"/Oh thanks. I'm glad it worked out/"},{"start":1046.2,"end":1052.33,"text":"Start with \\"Oh, thanks!\\" — warm, immediate, real.","words":[["Start with \\"Oh, thanks!\\" — warm, immediate, real.",1046.2]],"ipa":"/Start with \\"Oh, thanks!\\" — warm, immediate, real/"},{"start":1052.33,"end":1057.7,"text":"\\"I'm glad it worked out\\" adds a little more without overthinking.","words":[["\\"I'm glad it worked out\\" adds a little more without overthinking.",1052.33]],"ipa":"/I'm glad it worked out\\" adds a little more without overthinking/"},{"start":1057.7,"end":1069.73,"text":"Receiving compliments in English - - \\"Thanks, I'm glad\\" - - is one of the most common and most-practiced moments! Own it! 5 conversations!","words":[["Receiving compliments in English -",1057.7],["- \\"Thanks, I'm glad\\" -",1059.83],["- is one of the most common and most-practiced moments!",1061.83],["Own it!",1065.57],["5 conversations!",1067.47]],"ipa":"/Receiving compliments in English Thanks, I'm glad is one of the most common and most-practiced moments Own it ˌkɑnvərˈseɪʃənz/"},{"start":1069.8,"end":1073.8,"text":"5 times you answered before you finished thinking!","words":[["5 times you answered before you finished thinking!",1069.8]],"ipa":"/5 times you answered before you finished thinking/"},{"start":1073.8,"end":1078.13,"text":"5 times—it worked!","words":[["5 times—it worked!",1073.8]],"ipa":"/5 times—it worked/"},{"start":1078.2,"end":1080.43,"text":"This is the Speed Round.","words":[["This is the Speed Round.",1078.2]],"ipa":"/This is the Speed Round/"},{"start":1080.43,"end":1084.6,"text":"Warning: this section is faster than anything we’ve done today.","words":[["Warning: this section is faster than anything we’ve done today.",1080.43]],"ipa":"/Warning: this section is faster than anything we’ve done today/"},{"start":1084.6,"end":1089.8,"text":"If it feels uncomfortable — that is exactly the point. Stay with it.","words":[["If it feels uncomfortable — that is exactly the point. Stay with it.",1084.6]],"ipa":"/If it feels uncomfortable — that is exactly the point. Stay with it/"},{"start":1089.8,"end":1096.47,"text":"This is Day 9's version of the Reflex Round — but for conversation. Ten questions.","words":[["This is Day 9's version of the Reflex Round — but for conversation.",1089.8],["Ten questions.",1094.9]],"ipa":"/This is Day 9's version of the Reflex Round — but for conversation Ten questions/"},{"start":1096.47,"end":1099.4,"text":"The moment you understand — open your mouth.","words":[["The moment you understand — open your mouth.",1096.47]],"ipa":"/The moment you understand — open your mouth/"},{"start":1099.4,"end":1103.2,"text":"Don’t wait for the perfect sentence. Just start talking.","words":[["Don’t wait for the perfect sentence. Just start talking.",1099.4]],"ipa":"/Don’t wait for the perfect sentence. Just start talking/"},{"start":1103.2,"end":1105.2,"text":"The answer will come out.","words":[["The answer will come out.",1103.2]],"ipa":"/The answer will come out/"},{"start":1105.2,"end":1107.6,"text":"If you miss one, don't stop!","words":[["If you miss one, don't stop!",1105.2]],"ipa":"/If you miss one, don't stop/"},{"start":1107.77,"end":1110.6,"text":"Keep going. Never break the momentum!","words":[["Keep going. Never break the momentum!",1107.77]],"ipa":"/Keep going. Never break the momentum/"},{"start":1110.97,"end":1114.17,"text":"Momentum is the whole point. Ready?","words":[["Momentum is the whole point.",1110.97],["Ready?",1113.6]],"ipa":"/Momentum is the whole point ˈrɛdi/"},{"start":1114.27,"end":1117.27,"text":"Here we go. Fast!","words":[["Here we go. Fast!",1114.27]],"ipa":"/Here we go. Fast/"},{"start":1122.5,"end":1125.27,"text":"→ I'm good, thanks.","words":[["→ I'm good, thanks.",1122.5]],"ipa":"/I'm good, thanks/"},{"start":1131.2,"end":1133.83,"text":"→ Just practicing my English.","words":[["→ Just practicing my English.",1131.2]],"ipa":"/Just practicing my English/"},{"start":1138.37,"end":1140.97,"text":"→ Not yet. About to.","words":[["→ Not yet. About to.",1138.37]],"ipa":"/Not yet. About to/"},{"start":1145.73,"end":1148.27,"text":"→ Maybe. Why, what's up?","words":[["→ Maybe. Why, what's up?",1145.73]],"ipa":"/Maybe. Why, what's up/"},{"start":1153.23,"end":1154.77,"text":"→ Pretty good. A little busy.","words":[["→ Pretty good. A little busy.",1153.23]],"ipa":"/Pretty good. A little busy/"},{"start":1159.1,"end":1161.6,"text":"→ Yeah, I'm fine. Thanks.","words":[["→ Yeah, I'm fine. Thanks.",1159.1]],"ipa":"/Yeah, I'm fine. Thanks/"},{"start":1165.87,"end":1167.73,"text":"→ Almost. One second.","words":[["→ Almost. One second.",1165.87]],"ipa":"/Almost. One second/"},{"start":1172.03,"end":1174.33,"text":"→ I think it's good. Yeah.","words":[["→ I think it's good. Yeah.",1172.03]],"ipa":"/I think it's good. Yeah/"},{"start":1178.73,"end":1181.57,"text":"→ No, first time actually.","words":[["→ No, first time actually.",1178.73]],"ipa":"/No, first time actually/"},{"start":1186.03,"end":1188.2,"text":"→ Yes please. That would be great.","words":[["→ Yes please. That would be great.",1186.03]],"ipa":"/Yes please. That would be great/"},{"start":1188.2,"end":1190.63,"text":"10 questions. 10 answers!","words":[["10 questions. 10 answers!",1188.2]],"ipa":"/10 questions. 10 answers/"},{"start":1190.7,"end":1193.2,"text":"All of them real. All of them fast.","words":[["All of them real. All of them fast.",1190.7]],"ipa":"/All of them real. All of them fast/"},{"start":1193.2,"end":1194.53,"text":"All of them yours.","words":[["All of them yours.",1193.2]],"ipa":"/All of them yours/"},{"start":1194.53,"end":1196.17,"text":"Now — final challenge.","words":[["Now — final challenge.",1194.53]],"ipa":"/Now — final challenge/"},{"start":1196.17,"end":1201.73,"text":"All ten, back to back. I ask. You answer. Go.","words":[["All ten, back to back. I ask. You answer. Go.",1196.17]],"ipa":"/All ten, back to back. I ask. You answer. Go/"},{"start":1202.23,"end":1209.3,"text":"\\"How are you?\\"","words":[["\\"How are you?\\"",1202.23]],"ipa":"/How are you/"},{"start":1209.3,"end":1216.67,"text":"\\"What are you doing?\\"","words":[["\\"What are you doing?\\"",1209.3]],"ipa":"/What are you doing/"},{"start":1216.67,"end":1223.87,"text":"\\"Did you eat?\\"","words":[["\\"Did you eat?\\"",1216.67]],"ipa":"/Did you eat/"},{"start":1223.87,"end":1232.03,"text":"\\"Are you free later?\\"","words":[["\\"Are you free later?\\"",1223.87]],"ipa":"/Are you free later/"},{"start":1232.03,"end":1254.73,"text":"\\"How was your day?\\" \\"You OK?\\" Ready?","words":[["\\"How was your day?\\"",1232.03],["\\"You OK?\\"",1239.73],["Ready?",1246.8]],"ipa":"/How was your day You OK ˈrɛdi/"},{"start":1255.3,"end":1262.17,"text":"\\"What do you think?\\"","words":[["\\"What do you think?\\"",1255.3]],"ipa":"/What do you think/"},{"start":1262.7,"end":1271.3,"text":"\\"Have you been here before?\\"","words":[["\\"Have you been here before?\\"",1262.7]],"ipa":"/Have you been here before/"},{"start":1271.63,"end":1278.43,"text":"\\"Can I help you?\\"","words":[["\\"Can I help you?\\"",1271.63]],"ipa":"/Can I help you/"},{"start":1278.43,"end":1284.6,"text":"That is fast English. And you just did it!","words":[["That is fast English. And you just did it!",1278.43]],"ipa":"/That is fast English. And you just did it/"},{"start":1284.77,"end":1290.3,"text":"Think about what happened today You didn't learn new vocabulary.","words":[["Think about what happened today",1284.77],["You didn't learn new vocabulary.",1287.8]],"ipa":"/Think about what happened today You didn't learn new vocabulary/"},{"start":1290.33,"end":1292.47,"text":"You didn't study new grammar.","words":[["You didn't study new grammar.",1290.33]],"ipa":"/You didn't study new grammar/"},{"start":1292.57,"end":1294.7,"text":"You removed the delay!","words":[["You removed the delay!",1292.57]],"ipa":"/You removed the delay/"},{"start":1294.83,"end":1298.1,"text":"That three-second gap between hearing and speaking.","words":[["That three-second gap between hearing and speaking.",1294.83]],"ipa":"/That three-second gap between hearing and speaking/"},{"start":1298.17,"end":1300.77,"text":"You made it smaller. Not gone.","words":[["You made it smaller. Not gone.",1298.17]],"ipa":"/You made it smaller. Not gone/"},{"start":1300.8,"end":1303.97,"text":"Smaller. And that is everything!","words":[["Smaller. And that is everything!",1300.8]],"ipa":"/Smaller. And that is everything/"},{"start":1303.97,"end":1307.37,"text":"Most people think fluency means knowing more.","words":[["Most people think fluency means knowing more.",1303.97]],"ipa":"/Most people think fluency means knowing more/"},{"start":1307.43,"end":1310,"text":"But watch any fluent speaker.","words":[["But watch any fluent speaker.",1307.43]],"ipa":"/But watch any fluent speaker/"},{"start":1310,"end":1312.2,"text":"They don't know every word.","words":[["They don't know every word.",1310]],"ipa":"/They don't know every word/"},{"start":1312.27,"end":1314.27,"text":"They don't have perfect grammar.","words":[["They don't have perfect grammar.",1312.27]],"ipa":"/They don't have perfect grammar/"},{"start":1314.33,"end":1318.17,"text":"What they have is less hesitation!","words":[["What they have is less hesitation!",1314.33]],"ipa":"/What they have is less hesitation/"},{"start":1318.17,"end":1321.47,"text":"You didn't get faster English today.","words":[["You didn't get faster English today.",1318.17]],"ipa":"/You didn't get faster English today/"},{"start":1321.53,"end":1326.53,"text":"You removed the delay. And that is fluency!","words":[["You removed the delay. And that is fluency!",1321.53]],"ipa":"/You removed the delay. And that is fluency/"},{"start":1326.53,"end":1330.67,"text":"Starting Day 8: You learned to respond.","words":[["Starting Day 8: You learned to respond.",1326.53]],"ipa":"/Starting Day 8: You learned to respond/"},{"start":1330.77,"end":1334.6,"text":"Day 9: You learned to respond faster!","words":[["Day 9: You learned to respond faster!",1330.77]],"ipa":"/Day 9: You learned to respond faster/"},{"start":1334.73,"end":1339,"text":"One day at a time. One second shorter each time.","words":[["One day at a time. One second shorter each time.",1334.73]],"ipa":"/One day at a time. One second shorter each time/"},{"start":1339.07,"end":1345.7,"text":"That is how fluency is built. And that is Day 9!","words":[["That is how fluency is built. And that is Day 9!",1339.07]],"ipa":"/That is how fluency is built. And that is Day 9/"},{"start":1345.8,"end":1351.23,"text":"Now, go to the comments and type \\"Day 9 done!\\"","words":[["Now, go to the comments and type \\"Day 9 done!\\"",1345.8]],"ipa":"/Now, go to the comments and type \\"Day 9 done/"},{"start":1351.23,"end":1353.43,"text":"Even a little faster counts!","words":[["Even a little faster counts!",1351.23]],"ipa":"/Even a little faster counts/"},{"start":1353.43,"end":1357.83,"text":"Even one answer that came out before you were ready. That counts!","words":[["Even one answer that came out before you were ready.",1353.43],["That counts!",1356.53]],"ipa":"/Even one answer that came out before you were ready That counts/"},{"start":1357.83,"end":1362.23,"text":"I read every comment, and I want to hear how it felt!","words":[["I read every comment, and I want to hear how it felt!",1357.83]],"ipa":"/I read every comment, and I want to hear how it felt/"},{"start":1362.23,"end":1371.23,"text":"And if you want to follow the full 30-day journey, - the complete playlist and schedule are in the pinned comment below.","words":[["And if you want to follow the full 30-day journey,",1362.23],["- the complete playlist and schedule are in the pinned comment below.",1365.3]],"ipa":"/And if you want to follow the full 30-day journey the complete playlist and schedule are in the pinned comment below/"},{"start":1371.23,"end":1375.2,"text":"Now, Day 10: Day 10 is small talk!","words":[["Now, Day 10: Day 10 is small talk!",1371.23]],"ipa":"/Now, Day 10: Day 10 is small talk/"},{"start":1375.23,"end":1378.63,"text":"And small talk is where everything changes.","words":[["And small talk is where everything changes.",1375.23]],"ipa":"/And small talk is where everything changes/"},{"start":1378.63,"end":1381.53,"text":"Because small talk is not small!","words":[["Because small talk is not small!",1378.63]],"ipa":"/Because small talk is not small/"},{"start":1381.53,"end":1384.2,"text":"It is how relationships start.","words":[["It is how relationships start.",1381.53]],"ipa":"/It is how relationships start/"},{"start":1384.2,"end":1386.7,"text":"It is how trust is built!","words":[["It is how trust is built!",1384.2]],"ipa":"/It is how trust is built/"},{"start":1386.7,"end":1392.03,"text":"It is how people decide, in the first 30 seconds, - whether they like you.","words":[["It is how people decide, in the first 30 seconds,",1386.7],["- whether they like you.",1390.13]],"ipa":"/It is how people decide, in the first 30 seconds whether they like you/"},{"start":1392.03,"end":1394.57,"text":"Day 10 — we train for that moment.","words":[["Day 10 — we train for that moment.",1392.03]],"ipa":"/Day 10 — we train for that moment/"},{"start":1394.67,"end":1397.9,"text":"See you in Day 10! Keep speaking.","words":[["See you in Day 10!",1394.67],["Keep speaking.",1396.6]],"ipa":"/See you in Day 10 Keep speaking/"},{"start":1397.9,"end":1399.73,"text":"Keep starting sooner.","words":[["Keep starting sooner.",1397.9]],"ipa":"/Keep starting sooner/"},{"start":1399.73,"end":1400.03,"text":"Don't break your streak!","words":[["Don't break your streak!",1399.73]],"ipa":"/Don't break your streak/"},{"start":1117.73,"end":1125.17,"text":"\\"How are you?\\"","words":[["\\"How are you?\\"",1117.73]],"ipa":"/How are you/"},{"start":1125.17,"end":1133.53,"text":"\\"What are you doing?\\"","words":[["\\"What are you doing?\\"",1125.17]],"ipa":"/What are you doing/"},{"start":1133.77,"end":1140.77,"text":"\\"Did you eat?\\"","words":[["\\"Did you eat?\\"",1133.77]],"ipa":"/Did you eat/"},{"start":1141.1,"end":1148.17,"text":"\\"Are you free later?\\"","words":[["\\"Are you free later?\\"",1141.1]],"ipa":"/Are you free later/"},{"start":1148.27,"end":1167.47,"text":"\\"How was your day?\\" \\"You OK?\\" Ready?","words":[["\\"How was your day?\\"",1148.27],["\\"You OK?\\"",1154.77],["Ready?",1161.6]],"ipa":"/How was your day You OK ˈrɛdi/"},{"start":1167.73,"end":1174,"text":"\\"What do you think?\\"","words":[["\\"What do you think?\\"",1167.73]],"ipa":"/What do you think/"},{"start":1174.33,"end":1181.47,"text":"\\"You been here before?\\"","words":[["\\"You been here before?\\"",1174.33]],"ipa":"/You been here before/"},{"start":1181.57,"end":1187.73,"text":"\\"Can I help you?\\"","words":[["\\"Can I help you?\\"",1181.57]],"ipa":"/Can I help you/"}]`),u={id:e,youtubeId:t,title:o,channel:a,level:"A1",group:s,order:40,duration:1404,captions:r,segments:n};export{r as captions,a as channel,u as default,h as duration,s as group,e as id,i as level,d as order,n as segments,o as title,t as youtubeId};
